1	import { join } from "node:path";
2	import { serve } from "@hono/node-server";
3	import { defaultVisibility, type Product } from "@organic/shared";
4	import { createApp } from "./app";
5	import { loadConfig } from "./config";
6	import { createTtlCache } from "./lib/cache";
7	import { createCatalogService } from "./lib/catalog";
8	import { createSnapshotSource } from "./lib/snapshot";
9	import { createAdminSettingsStore } from "./lib/store/admin-settings";
10	import { createBasketStore } from "./lib/store/baskets";
11	import { createKarashynyardAdapter } from "./shops/karashynyard";
12	import { createOsioAdapter } from "./shops/osio";
13	
14	const config = loadConfig();
15	const shopFetch = (url: string, init?: { headers?: Record<string, string> }) =>
16	  fetch(url, { ...init, signal: AbortSignal.timeout(10_000) });
17	
18	// What the admin saved wins over DATA_SOURCE; a corrupt settings file crashes startup with the zod message.
19	const settingsStore = createAdminSettingsStore(join(config.dataDir, "admin-settings.json"), {
20	  dataSource: config.dataSource,
21	  visibility: defaultVisibility(),
22	});
23	const settings = await settingsStore.read();
24	
25	const catalog = createCatalogService({
26	  source: settings.dataSource,
27	  shops: [
28	    { adapter: createKarashynyardAdapter({ fetch: shopFetch }), snapshotKey: "karashynyard" },
29	    { adapter: createOsioAdapter({ fetch: shopFetch }), snapshotKey: "osio" },
30	  ],
31	  snapshots: createSnapshotSource(config.snapshotDir),
32	  cache: createTtlCache<Product[]>({ ttlMs: 300_000, now: Date.now }),
33	  now: Date.now,
34	  settings: settingsStore,
35	});
36	
37	const basketStore = createBasketStore(join(config.dataDir, "baskets.json"));
38	const app = createApp({ catalog, basketStore, settingsStore, adminToken: config.adminToken });
39	
40	serve({ fetch: app.fetch, port: config.port }, (info) => {
41	  console.log(`organic-catalog-api listening on http://localhost:${info.port}`);
42	});
43

