      });
      if (!stored) return { ok: false, error: "Basket item not found" };
      return { ok: true, basket: await toResponse(id, stored) };
    },

    async clear(id) {
      const stored = await store.update(id, () => ({ updatedAt: timestamp(), items: [] }));
      return toResponse(id, stored);
    },
  };
}

